  'cs.rubrics_help': 'உங்கள் சொந்த மதிப்பீட்டு அளவுகோல்கள். நீங்கள் பயிற்றுவிக்கும் விளையாட்டுகளுக்கான நிலையான அளவுகோல்கள் (FIFA, ICC, ஒலிம்பிக் …) உங்களுக்காகச் சேர்க்கப்படும் — அவற்றை மாற்றலாம், சேர்க்கலாம் அல்லது காப்பகப்படுத்தலாம். ஒரு ரூப்ரிக் பல விளையாட்டுகளை உள்ளடக்கலாம், ஒரு விளையாட்டுக்குப் பல ரூப்ரிக்குகள் இருக்கலாம். ஒவ்வொரு மதிப்பெண்ணும் வழங்கிய பதிப்புடன் இருக்கும்; வெவ்வேறு அளவுகோல்களின் மதிப்பெண்கள் ஒருபோதும் கலக்கப்படாது அல்லது அதிகாரப்பூர்வ புள்ளிவிவரங்களாக மாற்றப்படாது.',
