  "gst.saved": "ஜிஎஸ்டி சுயவிவரம் சேமிக்கப்பட்டது",
  "pay.upi.app": "என் UPI செயலியைத் திற",
  "pay.upi.or": "அல்லது உங்கள் UPI ID க்கு கோரிக்கை அனுப்பவும்",
